--- counter.ts	
+++ counter.ts	
@@ -1,11 +1,15 @@
 // A tiny in-memory counter service.
 export class Counter {
   private value = 0
   increment() {
     this.value += 1
     return this.value
   }
+  decrement() {
+    this.value = Math.max(0, this.value - 1)
+    return this.value
+  }
   get() {
     return this.value
   }
 }

